});

pm.collectionVariables.set("contactId", pm.response.json()._id);
pm.collectionVariables.set("contactFirstName", pm.response.json().firstName);
pm.collectionVariables.set("contactLastName", pm.response.json().lastName);
pm.collectionVariables.set("contactBirthdate", pm.response.json().birthdate);
pm.collectionVariables.set("contactEmail", pm.response.json().email);
pm.collectionVariables.set("contactPhone", pm.response.json().phone);
pm.collectionVariables.set("contactStreet1", pm.response.json().street1);
pm.collectionVariables.set("contactStreet2", pm.response.json().street2);
pm.collectionVariables.set("contactCity", pm.response.json().city);
pm.collectionVariables.set("contactStateProvince", pm.response.json().stateProvince);
pm.collectionVariables.set("contactPostalCode", pm.response.json().postalCode);
