pm.test("CP-012: Rechaza consulta con ID inválido (400 Bad Request)", function () {
    pm.response.to.have.status(400);
});

pm.test("CP-005 Consulta de información del perfil de usuario autenticado", function () {
    pm.response.to.have.status(200);
    pm.expect(pm.response.json().firstName).to.eql(pm.collectionVariables.get("Nombre"));
    pm.expect(pm.response.json().lastName).to.eql(pm.collectionVariables.get("Apellido"));
    pm.expect(pm.response.json().email).to.eql(pm.collectionVariables.get("Correo"));
    pm.expect(pm.response).to.not.have.property("password")
});

pm.test("CP-002 Modificación de perfil de usuario sin cabecera de autorización", function () {
    pm.response.to.have.status(401);
    pm.expect(pm.response.text()).to.include("Please authenticate.");
});

let data = pm.response.json();
let name = data.firstName
let lastname = data.lastName
pm.test("CP-007 Actualización parcial del perfil de usuario (PATCH)", function () {
    pm.response.to.have.status(200);
    pm.expect(name).to.not.equal(pm.collectionVariables.get("Nombre"));
    pm.expect(lastname).to.not.equal(pm.collectionVariables.get("Apellido"));
});

pm.collectionVariables.set("Nombre", name);
pm.collectionVariables.set("Apellido", lastname);

pm.test("CP-001 Autenticación exitosa (Login)", function () {
    pm.response.to.have.status(200);
});


let data = pm.response.json();
let tokenAuth = data.token;
pm.collectionVariables.set("tokenAuth", tokenAuth);

pm.test("CP-01 Verificar captura de token", function () {
    pm.expect(pm.collectionVariables.get("tokenAuth")).to.not.be.undefined;
});

pm.test("CP-014: Rechaza login con cuerpo vacío", function () {
    pm.response.to.have.status(400);
});

pm.test("CP-008 Eliminación definitiva de cuenta de usuario autenticado", function () {
    pm.response.to.have.status(200);
});

pm.test("CP-003 Eliminación de cuenta con esquema de autorización malformado", function () {
    pm.expect(pm.response.json().error).to.eql("Please authenticate.");
    pm.expect(pm.response.code).to.eql(401);
});
